function formatTime(n){const m=Math.floor(n/60),s=Math.floor(n%60);return`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawTrack(){ctx.fillStyle='#387a4c';ctx.fillRect(0,0,1000,700);ctx.fillStyle='#438650';for(let i=0;i<55;i++){const x=(i*173+37)%1000,y=(i*293+11)%700;ctx.beginPath();ctx.ellipse(x,y,22+(i%5)*7,8+(i%4)*4,i*.43,0,TAU);ctx.fill()}decor.forEach(d=>drawDecoration(d));ctx.save();ctx.translate(0,0);drawPath('#d8cda3',102);drawPath('#efe8cd',95);drawPath('#43845a',82);drawPath('#263d36',65);drawPath('#38443d',60);drawPath('#485149',57);ctx.restore();drawCurbs();drawCenterDash();drawFinish()}
function drawPath(color,width){ctx.beginPath();path.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke()}
function drawDecoration(d){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);const z=d.size;if(d.type==='palm'){ctx.fillStyle='#5e4430';ctx.beginPath();ctx.ellipse(0,7*z,5*z,15*z,-.15,0,TAU);ctx.fill();ctx.fillStyle='#176c47';for(let i=0;i<7;i++){const a=i*TAU/7;ctx.beginPath();ctx.ellipse(Math.cos(a)*13*z,-9*z+Math.sin(a)*8*z,17*z,4*z,a,0,TAU);ctx.fill()}ctx.fillStyle='#835b36';ctx.beginPath();ctx.arc(0,-8*z,5*z,0,TAU);ctx.fill()}else{ctx.fillStyle='#173c32';ctx.fillRect(-13*z,5*z,30*z,20*z);ctx.fillStyle=d.color;ctx.fillRect(-15*z,-5*z,30*z,20*z);ctx.fillStyle='#dbb85e';ctx.beginPath();ctx.moveTo(-19*z,-4*z);ctx.lineTo(0,-18*z);ctx.lineTo(19*z,-4*z);ctx.closePath();ctx.fill();ctx.fillStyle='#29483d';ctx.fillRect(-5*z,3*z,7*z,12*z);ctx.fillRect(7*z,1*z,6*z,6*z)}ctx.restore()}
function drawCurbs(){for(let i=0;i<path.length;i+=4){const a=path[i],b=path[(i+3)%path.length];const dist=Math.hypot(b.x-a.x,b.y-a.y),angle=Math.atan2(b.y-a.y,b.x-a.x);ctx.save();ctx.translate(a.x,a.y);ctx.rotate(angle);ctx.fillStyle=Math.floor(i/4)%2?'#fff1d2':'#e94445';ctx.fillRect(0,-49,dist+1,7);ctx.fillStyle=Math.floor(i/4)%2?'#e94445':'#fff1d2';ctx.fillRect(0,42,dist+1,7);ctx.restore()}}
function drawCenterDash(){ctx.save();ctx.setLineDash([11,13]);ctx.lineWidth=1.5;ctx.strokeStyle='#e2d9be4f';ctx.beginPath();path.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.stroke();ctx.restore()}
function drawFinish(){const p=pointAt(0);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.ang);for(let i=0;i<12;i++){ctx.fillStyle=i%2?'#fff':'#18201d';ctx.fillRect(-5+i*10,-28,10,9);ctx.fillStyle=i%2?'#18201d':'#fff';ctx.fillRect(-5+i*10,-19,10,9);ctx.fillStyle=i%2?'#fff':'#18201d';ctx.fillRect(-5+i*10,10,10,9);ctx.fillStyle=i%2?'#18201d':'#fff';ctx.fillRect(-5+i*10,19,10,9)}ctx.restore()}
function drawKart(x,y,ang,r,player){ctx.save();ctx.translate(x,y);ctx.rotate(ang);const sc=player?1.13:.92;ctx.scale(sc,sc);if(r.shield>0){ctx.strokeStyle=`rgba(135,226,255,${.6+.3*Math.sin(elapsed*13)})`;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,0,25,18,0,0,TAU);ctx.stroke();ctx.fillStyle='#4ac6ff20';ctx.fill()}if(r.hit>0&&Math.floor(elapsed*16)%2)ctx.globalAlpha=.45;ctx.fillStyle='#131b19';rr(-16,-11,32,8,3);ctx.fill();rr(-16,4,32,8,3);ctx.fill();ctx.fillStyle=r.color;rr(-12,-16,24,32,7);ctx.fill();ctx.fillStyle=r.accent;rr(-7,-12,14,9,4);ctx.fill();ctx.fillStyle='#ffdca5';rr(-6,1,12,10,4);ctx.fill();ctx.fillStyle='#fff5cf';ctx.fillRect(-9,-16,5,3);ctx.fillRect(4,-16,5,3);ctx.fillStyle='#d5f17e';ctx.fillRect(-14,12,5,2);ctx.fillRect(9,12,5,2);if(player){ctx.fillStyle='#fff';ctx.font='bold 6px sans-serif';ctx.textAlign='center';ctx.fillText('RD',0,0)}ctx.restore()}
